-- Merge bundled legacy emails and bonuses without replacing normalized database data.
-- Existing database rows always win; only unambiguous missing rows are inserted.
create table if not exists public.supportos_bundled_legacy_migration_report (
 report_key text primary key,
 run_id text not null,
 entity text not null check (entity in ('project', 'project_email', 'welcome_bonus', 'welcome_bonus_translation')),
 source_key text not null,
 source_id text,
 database_id text,
 status text not null check (status in ('existing', 'legacy_only_added', 'ambiguous')),
 provenance text not null default 'bundled_legacy' check (provenance = 'bundled_legacy'),
 candidate_ids jsonb not null default '[]'::jsonb,
 created_at timestamptz not null default now()
);

create index if not exists supportos_bundled_legacy_report_run_status_idx
on public.supportos_bundled_legacy_migration_report (run_id, entity, status);

alter table public.supportos_bundled_legacy_migration_report enable row level security;

revoke all on table public.supportos_bundled_legacy_migration_report
from public, anon, authenticated;

grant select, insert on table public.supportos_bundled_legacy_migration_report
to service_role;

create or replace function pg_temp.supportos_normalize_bundled_text(value text)
returns text
language sql
immutable
parallel safe
set search_path = ''
as $function$
 select lower(regexp_replace(trim(coalesce(value, '')), '[[:space:]]+', ' ', 'g'));
$function$;

