begin
 select count(*) into projects_before from public.supportos_projects;
 select count(*) into emails_before from public.supportos_project_emails;
 select count(*) into bonuses_before from public.supportos_welcome_bonuses;
 select count(*) into translations_before from public.supportos_welcome_bonus_translations;

 create temporary table bundled_projects on commit drop as
 select
  'emails:' || (project->>'i') as source_key,
  'emails'::text as source_kind,
  project->>'i' as source_id,
  project->>'n' as name,
  project->>'s' as slug,
  pg_temp.supportos_normalize_bundled_text(project->>'s') as slug_key,
  null::text as sheet_id,
  null::text as source_url,
  nullif(project->>'h', '') as source_hash,
  nullif(project->>'u', '') as source_updated_at
 from jsonb_array_elements(email_data) project
 where nullif(trim(project->>'i'), '') is not null
  and nullif(trim(project->>'n'), '') is not null
  and nullif(trim(project->>'s'), '') is not null
 union all
 select
  'bonuses:' || (project->>'i'),
  'bonuses',
  project->>'i',
  project->>'n',
  project->>'s',
  pg_temp.supportos_normalize_bundled_text(project->>'s'),
  nullif(project->>'d', ''),
  nullif(project->>'u', ''),
  nullif(project->>'h', ''),
  nullif(project->>'x', '')
 from jsonb_array_elements(bonus_data) project
 where nullif(trim(project->>'i'), '') is not null
  and nullif(trim(project->>'n'), '') is not null
  and nullif(trim(project->>'s'), '') is not null;

 create unique index on bundled_projects (source_key);
 create index on bundled_projects (source_id);
 create index on bundled_projects (slug_key);

 create temporary table project_pre_resolution on commit drop as
 with source_ranked as (
  select
   source.*,
   greatest(
    count(*) over (partition by source_id),
    count(*) over (partition by slug_key)
   ) as source_conflict_count
  from bundled_projects source
 )
 select
  source.*,
  candidates.candidate_count,
  candidates.database_project_id,
  candidates.candidate_ids,
  case
   when source.source_conflict_count > 1 or candidates.candidate_count > 1 then 'ambiguous'
   when candidates.candidate_count = 1 then 'existing'
   else 'legacy_only'
  end as status
 from source_ranked source
 left join lateral (
  select
   count(*)::integer as candidate_count,
   min(candidate.id) as database_project_id,
   coalesce(jsonb_agg(candidate.id order by candidate.id), '[]'::jsonb) as candidate_ids
  from (
   select distinct project.id
   from public.supportos_projects project
   where project.id = source.source_id
    or lower(trim(project.slug)) = source.slug_key
  ) candidate
 ) candidates on true;

 create temporary table inserted_projects (
  source_key text primary key,
  database_project_id text not null
 ) on commit drop;

 with inserted as (
  insert into public.supportos_projects (
   id, name, slug, sheet_id, source_url, source_hash, created_at, updated_at
  )
  select
   source_id,
   name,
   slug,
   sheet_id,
   source_url,
   source_hash,
   coalesce(source_updated_at::timestamptz, now()),
   coalesce(source_updated_at::timestamptz, now())
  from project_pre_resolution
  where status = 'legacy_only'
  on conflict do nothing
  returning id
 )
 insert into inserted_projects (source_key, database_project_id)
 select source.source_key, inserted.id
 from inserted
 join project_pre_resolution source on source.source_id = inserted.id;

 create temporary table project_resolution on commit drop as
 select
  source.*,
  case
   when source.status = 'existing' then source.database_project_id
   when inserted.database_project_id is not null then inserted.database_project_id
   else null
  end as resolved_project_id,
  case
   when source.status = 'existing' then 'existing'
   when inserted.database_project_id is not null then 'legacy_only_added'
   else 'ambiguous'
  end as final_status
 from project_pre_resolution source
 left join inserted_projects inserted using (source_key);

 create unique index on project_resolution (source_key);
 create index on project_resolution (resolved_project_id);

 create temporary table bundled_emails on commit drop as
 with expanded as (
  select
   'emails:' || (project->>'i') as project_source_key,
   project->>'i' as project_source_id,
   pg_temp.supportos_normalize_bundled_text(project->>'s') as project_slug_key,
   nullif(project->>'u', '') as source_updated_at,
   address,
   position
  from jsonb_array_elements(email_data) project
  cross join lateral jsonb_array_elements(coalesce(project->'a', '[]'::jsonb))
   with ordinality addresses(address, position)
  where nullif(trim(address->>'e'), '') is not null
   and nullif(trim(address->>'t'), '') is not null
 ),
 normalized as (
  select
   project_source_key || ':' || position::text as source_key,
   coalesce(
    nullif(address->>'i', ''),
    'bundled-email-' || md5(
     project_slug_key || chr(31)
     || pg_temp.supportos_normalize_bundled_text(address->>'t') || chr(31)
     || lower(trim(address->>'e'))
    )
   ) as source_id,
   project_source_key,
   trim(address->>'t') as type,
   pg_temp.supportos_normalize_bundled_text(address->>'t') as type_key,
   lower(trim(address->>'e')) as email,
   lower(trim(address->>'e')) as email_key,
   nullif(address->>'n', '') as note,
   coalesce((address->>'o')::integer, position::integer - 1) as sort_order,
   source_updated_at
  from expanded
 )
 select
  normalized.*,
  greatest(
   count(*) over (partition by source_id),
   count(*) over (partition by project_source_key, type_key, email_key)
  ) as source_conflict_count
 from normalized;

 create unique index on bundled_emails (source_key);
 create index on bundled_emails (source_id);
 create index on bundled_emails (project_source_key, type_key, email_key);

 create temporary table email_pre_resolution on commit drop as
 select
  source.*,
  project.resolved_project_id,
  project.final_status as project_status,
  candidates.candidate_count,
  candidates.database_email_id,
  candidates.candidate_ids,
  candidates.all_in_resolved_project,
  case
   when project.final_status not in ('existing', 'legacy_only_added') then 'ambiguous'
   when source.source_conflict_count > 1 then 'ambiguous'
   when candidates.candidate_count > 1 then 'ambiguous'
   when candidates.candidate_count = 1 and not candidates.all_in_resolved_project then 'ambiguous'
   when candidates.candidate_count = 1 then 'existing'
   else 'legacy_only'
  end as status
 from bundled_emails source
 join project_resolution project on project.source_key = source.project_source_key
 left join lateral (
  select
   count(*)::integer as candidate_count,
   min(candidate.id) as database_email_id,
   coalesce(jsonb_agg(candidate.id order by candidate.id), '[]'::jsonb) as candidate_ids,
   coalesce(bool_and(candidate.project_id = project.resolved_project_id), false) as all_in_resolved_project
  from (
   select distinct email.id, email.project_id
   from public.supportos_project_emails email
   where email.id = source.source_id
    or (
     email.project_id = project.resolved_project_id
     and pg_temp.supportos_normalize_bundled_text(email.type) = source.type_key
     and lower(trim(email.email)) = source.email_key
    )
  ) candidate
 ) candidates on true;

 create temporary table inserted_emails (
  source_key text primary key,
  database_email_id text not null
 ) on commit drop;

 with inserted as (
  insert into public.supportos_project_emails (
   id, project_id, type, email, note, sort_order, created_at, updated_at
  )
  select
   source_id,
   resolved_project_id,
   type,
   email,
   note,
   greatest(sort_order, 0),
   coalesce(source_updated_at::timestamptz, now()),
   coalesce(source_updated_at::timestamptz, now())
  from email_pre_resolution
  where status = 'legacy_only'
  on conflict do nothing
  returning id
 )
 insert into inserted_emails (source_key, database_email_id)
 select source.source_key, inserted.id
 from inserted
 join email_pre_resolution source on source.source_id = inserted.id;

 create temporary table email_resolution on commit drop as
 select
  source.*,
  case
   when source.status = 'existing' then source.database_email_id
   when inserted.database_email_id is not null then inserted.database_email_id
   else null
  end as resolved_email_id,
  case
   when source.status = 'existing' then 'existing'
   when inserted.database_email_id is not null then 'legacy_only_added'
   else 'ambiguous'
  end as final_status
 from email_pre_resolution source
 left join inserted_emails inserted using (source_key);

 create temporary table bundled_bonuses on commit drop as
 with expanded as (
  select
   'bonuses:' || (project->>'i') as project_source_key,
   project->>'i' as project_source_id,
   bonus,
   position
  from jsonb_array_elements(bonus_data) project
  cross join lateral jsonb_array_elements(coalesce(project->'b', '[]'::jsonb))
   with ordinality bonuses(bonus, position)
 )
 select
  project_source_key || ':' || (bonus->>'i') as source_key,
  bonus->>'i' as source_id,
  project_source_key,
  trim(bonus->>'n') as name,
  pg_temp.supportos_normalize_bundled_text(bonus->>'n') as name_key,
  nullif(bonus->>'a', '')::numeric as min_deposit_amount,
  upper(trim(coalesce(bonus->>'c', ''))) as min_deposit_currency_key,
  nullif(trim(bonus->>'c'), '') as min_deposit_currency,
  greatest(coalesce((bonus->>'o')::integer, position::integer - 1), 0) as sort_order,
  nullif(bonus->>'v', '')::date as valid_until,
  nullif(bonus->>'r', '')::date as review_due,
  nullif(bonus->>'k', '')::timestamptz as checked_at,
  nullif(trim(bonus->>'p'), '') as responsible,
  coalesce(bonus->'t', '[]'::jsonb) as translations,
  count(*) over (partition by bonus->>'i') as source_conflict_count
 from expanded
 where nullif(trim(bonus->>'i'), '') is not null
  and nullif(trim(bonus->>'n'), '') is not null;

 create unique index on bundled_bonuses (source_key);
 create index on bundled_bonuses (source_id);
 create index on bundled_bonuses (project_source_key);

 create temporary table bundled_bonus_identifiers on commit drop as
 select distinct
  bonus.source_key,
  md5(
   lower(trim(translation->>'l')) || chr(31)
   || pg_temp.supportos_normalize_bundled_text(translation->>'c')
  ) as identifier
 from bundled_bonuses bonus
 cross join lateral jsonb_array_elements(bonus.translations) translation
 where nullif(trim(translation->>'l'), '') is not null
  and nullif(pg_temp.supportos_normalize_bundled_text(translation->>'c'), '') is not null;

 create index on bundled_bonus_identifiers (identifier);
 create index on bundled_bonus_identifiers (source_key);

 create temporary table database_bonus_identifiers on commit drop as
 select distinct
  translation.welcome_bonus_id as database_bonus_id,
  md5(
   lower(trim(translation.language)) || chr(31)
   || pg_temp.supportos_normalize_bundled_text(translation.content)
  ) as identifier
 from public.supportos_welcome_bonus_translations translation
 where nullif(trim(translation.language), '') is not null
  and nullif(pg_temp.supportos_normalize_bundled_text(translation.content), '') is not null;

 create index on database_bonus_identifiers (identifier);
 create index on database_bonus_identifiers (database_bonus_id);

 create temporary table bonus_candidate_scores on commit drop as
 with candidate_pairs as (
  select source.source_key, bonus.id as database_bonus_id
  from bundled_bonuses source
  join public.supportos_welcome_bonuses bonus on bonus.id = source.source_id
  union
  select source_identifier.source_key, bonus.id
  from bundled_bonus_identifiers source_identifier
  join database_bonus_identifiers database_identifier using (identifier)
  join public.supportos_welcome_bonuses bonus on bonus.id = database_identifier.database_bonus_id
  join bundled_bonuses source on source.source_key = source_identifier.source_key
  join project_resolution project on project.source_key = source.project_source_key
  where project.resolved_project_id is not null
   and bonus.project_id = project.resolved_project_id
  union
  select source.source_key, bonus.id
  from bundled_bonuses source
  join project_resolution project on project.source_key = source.project_source_key
  join public.supportos_welcome_bonuses bonus on bonus.project_id = project.resolved_project_id
  where pg_temp.supportos_normalize_bundled_text(bonus.name) = source.name_key
   and bonus.min_deposit_amount is not distinct from source.min_deposit_amount
   and upper(trim(coalesce(bonus.min_deposit_currency, ''))) = source.min_deposit_currency_key
   and bonus.sort_order = source.sort_order
 )
 select
  pair.source_key,
  pair.database_bonus_id,
  case when database_bonus.id = source.source_id then 1 else 0 end as id_match,
  (
   select count(*)::integer
   from bundled_bonus_identifiers source_identifier
   join database_bonus_identifiers database_identifier using (identifier)
   where source_identifier.source_key = pair.source_key
    and database_identifier.database_bonus_id = pair.database_bonus_id
  ) as content_matches,
  case
   when database_bonus.project_id = project.resolved_project_id
    and pg_temp.supportos_normalize_bundled_text(database_bonus.name) = source.name_key
    and database_bonus.min_deposit_amount is not distinct from source.min_deposit_amount
    and upper(trim(coalesce(database_bonus.min_deposit_currency, ''))) = source.min_deposit_currency_key
    and database_bonus.sort_order = source.sort_order
   then 1 else 0
  end as structure_match,
  (
   (case when database_bonus.id = source.source_id then 1 else 0 end)::bigint * 1000000000000
   + (
    select count(*)::bigint
    from bundled_bonus_identifiers source_identifier
    join database_bonus_identifiers database_identifier using (identifier)
    where source_identifier.source_key = pair.source_key
     and database_identifier.database_bonus_id = pair.database_bonus_id
   ) * 1000000
   + case
      when database_bonus.project_id = project.resolved_project_id
       and pg_temp.supportos_normalize_bundled_text(database_bonus.name) = source.name_key
       and database_bonus.min_deposit_amount is not distinct from source.min_deposit_amount
       and upper(trim(coalesce(database_bonus.min_deposit_currency, ''))) = source.min_deposit_currency_key
       and database_bonus.sort_order = source.sort_order
      then 1000 else 0
     end
  )::bigint as score
 from candidate_pairs pair
 join bundled_bonuses source using (source_key)
 join project_resolution project on project.source_key = source.project_source_key
 join public.supportos_welcome_bonuses database_bonus on database_bonus.id = pair.database_bonus_id;

 create index on bonus_candidate_scores (source_key, score desc);
 create index on bonus_candidate_scores (database_bonus_id, score desc);

 create temporary table resolved_existing_bonuses on commit drop as
 with maxima as (
  select
   candidate.*,
   max(score) over (partition by source_key) as source_best_score,
   max(score) over (partition by database_bonus_id) as database_best_score
  from bonus_candidate_scores candidate
 ),
 reciprocal_best as (
  select *
  from maxima
  where score = source_best_score
   and score = database_best_score
 ),
 choices as (
  select
   reciprocal_best.*,
   count(*) over (partition by source_key) as source_choice_count,
   count(*) over (partition by database_bonus_id) as database_choice_count
  from reciprocal_best
 )
 select choices.source_key, choices.database_bonus_id
 from choices
 join bundled_bonuses source using (source_key)
 join project_resolution project on project.source_key = source.project_source_key
 join public.supportos_welcome_bonuses bonus on bonus.id = choices.database_bonus_id
 where choices.source_choice_count = 1
  and choices.database_choice_count = 1
  and project.resolved_project_id is not null
  and bonus.project_id = project.resolved_project_id;

 create unique index on resolved_existing_bonuses (source_key);
 create unique index on resolved_existing_bonuses (database_bonus_id);

 create temporary table bonus_pre_resolution on commit drop as
 select
  source.*,
  project.resolved_project_id,
  project.final_status as project_status,
  existing.database_bonus_id,
  candidates.candidate_count,
  candidates.candidate_ids,
  case
   when project.final_status not in ('existing', 'legacy_only_added') then 'ambiguous'
   when source.source_conflict_count > 1 then 'ambiguous'
   when existing.database_bonus_id is not null then 'existing'
   when candidates.candidate_count > 0 then 'ambiguous'
   else 'legacy_only'
  end as status
 from bundled_bonuses source
 join project_resolution project on project.source_key = source.project_source_key
 left join resolved_existing_bonuses existing
  on existing.source_key = source.source_key
 left join lateral (
  select
   count(*)::integer as candidate_count,
   coalesce(jsonb_agg(candidate.database_bonus_id order by candidate.score desc, candidate.database_bonus_id), '[]'::jsonb) as candidate_ids
  from bonus_candidate_scores candidate
  where candidate.source_key = source.source_key
 ) candidates on true;

 create temporary table inserted_bonuses (
  source_key text primary key,
  database_bonus_id text not null
 ) on commit drop;

 with inserted as (
  insert into public.supportos_welcome_bonuses (
   id, project_id, name, min_deposit_amount, min_deposit_currency, sort_order,
   valid_until, review_due, checked_at, responsible
  )
  select
   source_id,
   resolved_project_id,
   name,
   min_deposit_amount,
   min_deposit_currency,
   sort_order,
   valid_until,
   review_due,
   checked_at,
   responsible
  from bonus_pre_resolution
  where status = 'legacy_only'
  on conflict do nothing
  returning id
 )
 insert into inserted_bonuses (source_key, database_bonus_id)
 select source.source_key, inserted.id
 from inserted
 join bonus_pre_resolution source on source.source_id = inserted.id;

 create temporary table bonus_resolution on commit drop as
 select
  source.*,
  case
   when source.status = 'existing' then source.database_bonus_id
   when inserted.database_bonus_id is not null then inserted.database_bonus_id
   else null
  end as resolved_bonus_id,
  case
   when source.status = 'existing' then 'existing'
   when inserted.database_bonus_id is not null then 'legacy_only_added'
   else 'ambiguous'
  end as final_status
 from bonus_pre_resolution source
 left join inserted_bonuses inserted using (source_key);

 create temporary table bundled_translations on commit drop as
 with expanded as (
  select
   bonus.source_key as bonus_source_key,
   bonus.source_id as bonus_source_id,
   translation,
   position
  from bundled_bonuses bonus
  cross join lateral jsonb_array_elements(bonus.translations)
   with ordinality translations(translation, position)
 ),
 normalized as (
  select
   bonus_source_key || ':' || lower(trim(translation->>'l')) as source_key,
   bonus_source_id || ':' || lower(trim(translation->>'l')) as source_id,
   bonus_source_key,
   lower(trim(translation->>'l')) as language,
   translation->>'c' as content,
   nullif(translation->>'u', '') as source_updated_at
  from expanded
  where length(trim(translation->>'l')) between 2 and 16
 )
 select
  normalized.*,
  count(*) over (partition by bonus_source_key, language) as source_conflict_count
 from normalized;

 create index on bundled_translations (bonus_source_key, language);

 create temporary table translation_pre_resolution on commit drop as
 select
  source.*,
  bonus.resolved_bonus_id,
  bonus.final_status as bonus_status,
  existing.welcome_bonus_id is not null as already_exists,
  case
   when bonus.final_status not in ('existing', 'legacy_only_added') then 'ambiguous'
   when source.source_conflict_count > 1 then 'ambiguous'
   when existing.welcome_bonus_id is not null then 'existing'
   else 'legacy_only'
  end as status
 from bundled_translations source
 join bonus_resolution bonus on bonus.source_key = source.bonus_source_key
 left join public.supportos_welcome_bonus_translations existing
  on existing.welcome_bonus_id = bonus.resolved_bonus_id
  and existing.language = source.language;

 create temporary table inserted_translations (
  source_key text primary key,
  database_translation_id text not null
 ) on commit drop;

 with inserted as (
  insert into public.supportos_welcome_bonus_translations (
   welcome_bonus_id, language, content, created_at, updated_at
  )
  select
   resolved_bonus_id,
   language,
   content,
   coalesce(source_updated_at::timestamptz, now()),
   coalesce(source_updated_at::timestamptz, now())
  from translation_pre_resolution
  where status = 'legacy_only'
  on conflict do nothing
  returning welcome_bonus_id, language
 )
 insert into inserted_translations (source_key, database_translation_id)
 select
  source.source_key,
  inserted.welcome_bonus_id || ':' || inserted.language
 from inserted
 join translation_pre_resolution source
  on source.resolved_bonus_id = inserted.welcome_bonus_id
  and source.language = inserted.language;

 create temporary table translation_resolution on commit drop as
 select
  source.*,
  case
   when source.status = 'existing' then source.resolved_bonus_id || ':' || source.language
   when inserted.database_translation_id is not null then inserted.database_translation_id
   else null
  end as resolved_translation_id,
  case
   when source.status = 'existing' then 'existing'
   when inserted.database_translation_id is not null then 'legacy_only_added'
   else 'ambiguous'
  end as final_status
 from translation_pre_resolution source
 left join inserted_translations inserted using (source_key);

 create temporary table migration_results on commit drop as
 select
  'project'::text as entity,
  source_key,
  source_id,
  resolved_project_id as database_id,
  final_status as status,
  candidate_ids
 from project_resolution
 union all
 select
  'project_email',
  source_key,
  source_id,
  resolved_email_id,
  final_status,
  candidate_ids
 from email_resolution
 union all
 select
  'welcome_bonus',
  source_key,
  source_id,
  resolved_bonus_id,
  final_status,
  candidate_ids
 from bonus_resolution
 union all
 select
  'welcome_bonus_translation',
  source_key,
  source_id,
  resolved_translation_id,
  final_status,
  case
   when final_status = 'existing'
   then jsonb_build_array(resolved_bonus_id || ':' || language)
   else '[]'::jsonb
  end
 from translation_resolution;

 insert into public.supportos_bundled_legacy_migration_report (
  report_key, run_id, entity, source_key, source_id, database_id,
  status, provenance, candidate_ids
 )
 select
  migration_run || ':' || entity || ':' || source_key,
  migration_run,
  entity,
  source_key,
  source_id,
  database_id,
  status,
  'bundled_legacy',
  candidate_ids
 from migration_results
 on conflict (report_key) do nothing;

 select count(*) into projects_after from public.supportos_projects;
 select count(*) into emails_after from public.supportos_project_emails;
 select count(*) into bonuses_after from public.supportos_welcome_bonuses;
 select count(*) into translations_after from public.supportos_welcome_bonus_translations;

 if projects_after <> projects_before + (select count(*) from inserted_projects) then
  raise exception 'Bundled project count verification failed: before=%, after=%', projects_before, projects_after;
 end if;
 if emails_after <> emails_before + (select count(*) from inserted_emails) then
  raise exception 'Bundled email count verification failed: before=%, after=%', emails_before, emails_after;
 end if;
 if bonuses_after <> bonuses_before + (select count(*) from inserted_bonuses) then
  raise exception 'Bundled bonus count verification failed: before=%, after=%', bonuses_before, bonuses_after;
 end if;
 if translations_after <> translations_before + (select count(*) from inserted_translations) then
  raise exception 'Bundled translation count verification failed: before=%, after=%', translations_before, translations_after;
 end if;

 select jsonb_agg(
  jsonb_build_object(
   'entity', entity,
   'source', source_count,
   'db_before', db_before,
   'existing', existing_count,
   'legacy_only_added', added_count,
   'ambiguous', ambiguous_count,
   'db_after', db_after
  )
  order by entity
 )
 into summary
 from (
  select
   entity,
   count(*)::bigint as source_count,
   case entity
    when 'project' then projects_before
    when 'project_email' then emails_before
    when 'welcome_bonus' then bonuses_before
    else translations_before
   end as db_before,
   count(*) filter (where status = 'existing')::bigint as existing_count,
   count(*) filter (where status = 'legacy_only_added')::bigint as added_count,
   count(*) filter (where status = 'ambiguous')::bigint as ambiguous_count,
   case entity
    when 'project' then projects_after
    when 'project_email' then emails_after
    when 'welcome_bonus' then bonuses_after
    else translations_after
   end as db_after
  from migration_results
  group by entity
 ) counts;

 select coalesce(
  jsonb_agg(
   jsonb_build_object(
    'entity', entity,
    'sourceId', source_id,
    'sourceKey', source_key,
    'candidateIds', candidate_ids
   )
   order by entity, source_key
  ),
  '[]'::jsonb
 )
 into ambiguous_report
 from migration_results
 where status = 'ambiguous';

 raise notice 'Bundled legacy merge counts: %', summary;
 raise notice 'Bundled legacy ambiguous report: %', ambiguous_report;
end
$migration$;
